313009,"487":330011,"488":332046,"489":331806,"490":332048,"491":333028,"492":1512,"493":1513,"494":2704,"495":215121,"496":215131,"497":227041,"498":312035,"499":312036,"500":321029,"501":321030,"502":322029,"503":322030,"504":332049,"505":332050,"506":1414,"507":1514,"508":2305,"509":214141,"510":215141,"511":223051,"512":312037,"513":312038,"514":312039,"515":332051,"516":332052,"517":332053,"518":332054,"519":332055,"520":311208,"521":1415,"522":1515,"523":2206,"524":214151,"525":215151,"526":222061,"527":311111,"528":312040,"529":312041,"530":321031,"531":332056,"532":333029,"533":1115,"534":1316,"535":2604,"536":211151,"537":213161,"538":226041,"539":312043,"540":322031,"541":330012,"542":332057,"543":332058,"544":1116,"545":1416,"546":2207,"547":211161,"548":214161,"549":222071,"550":311112,"551":311310,"552":312044,"553":322032,"554":332059,"555":1117,"556":1417,"557":2306,"558":211171,"559":214171,"560":223061,"561":321035,"562":321036,"563":321037,"564":321038,"565":321039,"566":331004,"567":331005,"568":332060,"569":332061,"570":1215,"571":1216,"572":2705,"573":212151,"574":212161,"575":227051,"576":311209,"577":313010,"578":322033,"579":331006,"580":331007,"581":331721,"582":331807,"583":332062,"584":1418,"585":1711,"586":2605,"587":214181,"588":217111,"589":226051,"590":312045,"591":322034,"592":331008,"593":331009,"594":330013,"595":333030,"596":1712,"597":2105,"598":2504,"599":217121,"600":221051,"601":225041,"602":321041,"603":331010,"604":331011,"605":332063,"606":332064,"607":333031,"608":1317,"609":1516,"610":2208,"611":213171,"612":215161,"613":222081,"614":212032,"615":213062,"616":214012,"617":215032,"618":332065,"619":332066,"620":1217,"621":1612,"622":212171,"623":214022,"624":215012,"625":216042,"626":216121,"627":312046,"628":331012,"629":330014,"630":1517,"631":213172,"632":215171,"633":215172,"634":312047,"635":322035,"636":331013,"637":330015}""")
ID2SID = {v: int(k) for k, v in SHARE_ID.items()}
BLOCK_WORDS = json.loads(r"""["1s","2c8","2g1c","4jg","4jk","5l3","64","6four","6iv","6si","89","8jiu","92f","99bb","a55","anal","anus","ass","ash0le","b00b","b1tch","b17ch","ba9","bb1","bbw","bdsm","beaner","bi7ch","bimbos","bitch","boob","boner","c0cks","c0n","c4","cag","ccp","chink","clit","cnm","cnn","cock","coons","cum","cunt","cuum","cv0","darkie","dick","dildo","dilld0","dommes","dpp","dvda","ecchi","erotic","f4k","fag1t","fagg1t","faggot","fck","fdp","fecal","felch","feltch","femdom","flg","fm2","fuck","gay","gcd","gdm","ggc","girlon","goatcx","goatse","gokkun","grope","guro","gwg","hentai","hitler","hjt","honkey","hooker","incest","j8","jba","ji8","jiba","jiz","juggs","jzm","k7","kike","kinky","kmt","kock","liu4","liusi","lolita","lsp","m0m","m2f","mh0","milf","mof0","nambla","negro","nignog","nigga","nigger","nipple","njink","nmd","ntd","ntr","nympho","orgasm","orgy","p0rn","p2np","p3t","paki","panty","pcp","penis","phuq","pig","poof","poon","porn","pqp","prr","pthc","pu55i","pu55y","pubes","puki","punany","pussy","queaf","queef","queer","quim","rape","raping","rapist","rbq","rectum","rimjob","s2x","s3x","sadism","scat","semen","sex","sh7t","shit","shota","six4","skeet","slut","slvt","smut","sodomy","spic","spooge","spunk","suck","t3k","t41","t43","t4e","t4i","tits","tiedup","titty","tmd","tosser","tranny","tushy","twat","twink","vagina","vi4","viiv","vpn","vulva","waf","wank","whore","wh0re","wtf","x3r","xdd","xjp","yaoi","yiffy"]""")
BLOCK_RE = re.compile("|".join("[+/]*".join(re.escape(ch) for ch in w) for w in BLOCK_WORDS), re.I)


def encode_raw(arr):
    if len(arr) != 33:
        raise ValueError("需要恰好 33 个 share id")
    padded = list(arr) + [0]
    reordered = []
    for i in range(17):
        reordered += [
            padded[2 * i] >> 4,
            ((padded[2 * i] & 0xF) << 4) + (padded[2 * i + 1] >> 8),
            (arr[2 * i + 1] if 2 * i + 1 < len(arr) else 0) & 0xFF,
        ]
    for last in range(0xFF):
        original = []
        for i in range(25):
            original += [(reordered[i] + last) & 0xFF, (reordered[i + 25] + last) & 0xFF]
        encoded = base64.b64encode(bytes(original + [last])).decode()
        if not BLOCK_RE.search(encoded):
            return encoded
    raise ValueError("找不到可用校验字节")


def decode_raw(src):
    src = src.strip()
    data = base64.b64decode(src + "=" * (-len(src) % 4))
    if len(data) != 51:
        raise ValueError("牌组码长度不对（应为 51 字节）")
    last = data[-1]
    arr = list(data[:-1])
    reordered = [(arr[2 * i] - last) & 0xFF for i in range(25)] + \
                [(arr[2 * i + 1] - last) & 0xFF for i in range(25)] + [0]
    result = []
    for i in range(17):
        result += [
            (reordered[3 * i] << 4) + (reordered[3 * i + 1] >> 4),
            ((reordered[3 * i + 1] & 0xF) << 8) + reordered[3 * i + 2],
        ]
    result.pop()
    return result


def encode_deck(ids):
    if len(ids) != 33:
        raise ValueError(f"需要 33 个卡牌 id（3 角色 + 30 行动牌），现在给了 {len(ids)} 个")
    unknown = [i for i in ids if i not in ID2SID]
    if unknown:
        raise ValueError("未知卡牌 id：" + ", ".join(map(str, unknown)))
    return encode_raw([ID2SID[i] for i in ids])


def decode_deck(code):
    raw = decode_raw(code)
    ids = []
    for sid in raw:
        if str(sid) not in SHARE_ID:
            raise ValueError(f"未知 share id {sid}")
        ids.append(SHARE_ID[str(sid)])
    return ids


def print_deck(ids):
    chars, cards = ids[:3], ids[3:]
    print(f"牌组码: {encode_deck(ids)}")
    print(f"角色: {' '.join(map(str, chars))}")
    counts = {}
    for c in cards:
        counts[c] = counts.get(c, 0) + 1
    print("行动牌: " + ", ".join(f"{cid}×{n}" for cid, n in counts.items()))


def parse_ids(tokens):
    ids = []
    for t in tokens:
        t = t.strip().rstrip(",")
        if not t:
            continue
        if not re.fullmatch(r"\d+", t):
            raise ValueError(f"不是数字: {t}")
        ids.append(int(t))
    return ids


def usage():
    print("""用法：
  deckcode.sh encode <33 个卡牌 id>
  deckcode.sh decode <牌组码>
  deckcode.sh same-card <行动牌 id> <角色1> <角色2> <角色3>   # 30 张同卡
  deckcode.sh same-char <角色 id> <行动牌 id>                 # 3 个同角色 + 30 张同卡
  deckcode.sh repeat <角色1> <角色2> <角色3> <行动牌 id...>   # 重复模式补到 30 张
  deckcode.sh batch <文件>        # 每行一组：牌组码或 33 个 id
""")

def main():
    if len(sys.argv) < 2:
        usage(); return 1
    mode = sys.argv[1]
    try:
        if mode in ("help", "-h", "--help"):
            usage(); return 0
        if mode == "encode":
            ids = parse_ids(sys.argv[2:])
            print_deck(ids); return 0
        if mode == "decode":
            if len(sys.argv) < 3: raise ValueError("缺少牌组码")
            print_deck(decode_deck(sys.argv[2])); return 0
        if mode == "same-card":
            if len(sys.argv) < 6: raise ValueError("需要 1 个行动牌 id + 3 个角色 id")
            card = int(sys.argv[2]); chars = [int(x) for x in sys.argv[3:6]]
            print_deck(chars + [card] * 30); return 0
        if mode == "same-char":
            if len(sys.argv) < 4: raise ValueError("需要角色 id 和行动牌 id")
            char, card = int(sys.argv[2]), int(sys.argv[3])
            print_deck([char] * 3 + [card] * 30); return 0
        if mode == "repeat":
            tokens = sys.argv[2:]
            if len(tokens) < 4: raise ValueError("需要 3 个角色 + 至少 1 张行动牌")
            chars = [int(x) for x in tokens[:3]]
            pattern = [int(x) for x in tokens[3:]]
            cards = [pattern[i % len(pattern)] for i in range(30)]
            print_deck(chars + cards); return 0
        if mode == "batch":
            if len(sys.argv) < 3: raise ValueError("缺少文件路径")
            for raw in open(sys.argv[2], encoding="utf-8"):
                line = raw.strip()
                if not line or line.startswith("#"):
                    continue
                toks = line.replace(",", " ").split()
                if len(toks) == 1 and not toks[0].isdigit():
                    print_deck(decode_deck(toks[0]))
                else:
                    print_deck(parse_ids(toks))
                print()
            return 0
        raise ValueError(f"未知模式: {mode}")
    except Exception as exc:
        print("错误:", exc, file=sys.stderr); return 1


if __name__ == "__main__":
    sys.exit(main())

PYEOF
